145	/// Reads and parses `pyproject_path` as TOML, if it exists. `Ok(None)` when
146	/// the file is absent -- not every package has a `pyproject.toml`.
147	///
148	/// Callers needing more than one field out of the same `pyproject.toml`
149	/// (e.g. both `[tool.maturin].targets` and `requires-python`, see
150	/// `build_matrix_report`) must call this once and pass the resulting
151	/// `Value` to each field-extraction function (`read_maturin_targets`,
152	/// `read_requires_python`) rather than letting each one independently
153	/// re-read and re-parse the file from disk.
154	pub(crate) fn parse_pyproject_toml(pyproject_path: &Path) -> Result<Option<toml::Value>, GraphError> {
155	    let Some(content) = callisto_model::strict_fs::read_optional(pyproject_path).map_err(|e| {
156	        GraphError::Manifest(ManifestError::Read {
157	            path: pyproject_path.to_path_buf(),
158	            message: e.to_string(),
159	        })
160	    })?
161	    else {
162	        return Ok(None);
163	    };
164	    let val = toml::from_str::<toml::Value>(&content).map_err(|e: toml::de::Error| {
165	        GraphError::Manifest(ManifestError::Parse {
166	            path: pyproject_path.to_path_buf(),
167	            format: ManifestFormat::PyprojectToml,
168	            message: e.to_string(),
169	        })
170	    })?;
171	    Ok(Some(val))
172	}
173	
174	/// Extracts `[tool.maturin].targets` from an already-parsed `pyproject.toml`
175	/// value (see `parse_pyproject_toml`). Returns `Ok(None)` when the table or
176	/// field is absent (no platformTargets entry). A present value that
177	/// is not a TOML array of strings is a hard error.
178	pub(crate) fn read_maturin_targets(
179	    pyproject_path: &Path,
180	    val: &toml::Value,
181	) -> Result<Option<Vec<String>>, GraphError> {
182	    let Some(targets) = val
183	        .get("tool")
184	        .and_then(|t| t.get("maturin"))
185	        .and_then(|m| m.get("targets"))
186	    else {
187	        return Ok(None);
188	    };
189	
190	    let arr = targets.as_array().ok_or_else(|| {
191	        GraphError::Manifest(ManifestError::Parse {
192	            path: pyproject_path.to_path_buf(),
193	            format: ManifestFormat::PyprojectToml,
194	            message: "[tool.maturin].targets must be an array of strings".to_string(),
195	        })
196	    })?;
197	
198	    let mut out = Vec::with_capacity(arr.len());
199	    for item in arr {
200	        let s = item.as_str().ok_or_else(|| {
201	            GraphError::Manifest(ManifestError::Parse {
202	                path: pyproject_path.to_path_buf(),
203	                format: ManifestFormat::PyprojectToml,
204	                message: "[tool.maturin].targets entries must all be strings".to_string(),
205	            })
206	        })?;
207	        out.push(s.to_string());
208	    }
209	    Ok(Some(out))
210	}
