212	/// Extracts `engines.node` as a raw string from an already-parsed
213	/// `package.json` value (see `parse_package_json`). `Ok(None)` when absent;
214	/// `Err` when present but not a JSON string.
215	pub(crate) fn read_engines_node(pkg_json_path: &Path, val: &serde_json::Value) -> Result<Option<String>, GraphError> {
216	    let Some(node) = val.get("engines").and_then(|e| e.get("node")) else {
217	        return Ok(None);
218	    };
219	    let s = node.as_str().ok_or_else(|| {
220	        GraphError::Manifest(ManifestError::Parse {
221	            path: pkg_json_path.to_path_buf(),
222	            format: ManifestFormat::PackageJson,
223	            message: "engines.node must be a string".to_string(),
224	        })
225	    })?;
226	    Ok(Some(s.to_string()))
227	}
