229	/// Extracts `requires-python` as a raw string from an already-parsed
230	/// `pyproject.toml` value (see `parse_pyproject_toml`). `Ok(None)` when
231	/// absent; `Err` when present but not a TOML string.
232	pub(crate) fn read_requires_python(pyproject_path: &Path, val: &toml::Value) -> Result<Option<String>, GraphError> {
233	    let Some(rp) = val.get("project").and_then(|p| p.get("requires-python")) else {
234	        return Ok(None);
235	    };
236	    let s = rp.as_str().ok_or_else(|| {
237	        GraphError::Manifest(ManifestError::Parse {
238	            path: pyproject_path.to_path_buf(),
239	            format: ManifestFormat::PyprojectToml,
240	            message: "requires-python must be a string".to_string(),
241	        })
242	    })?;
243	    Ok(Some(s.to_string()))
244	}
